import http from 'node:http';

const RATES_URL = 'https://api.exchangerate.host/latest';
const CACHE_TTL_MS = Number(process.env.RATES_CACHE_TTL_MS) || 10 * 60 * 1000;

// TODO: this cache is per-process/in-memory. Behind a multi-instance load
// balancer, each instance polls upstream independently and can serve
// different rates until they all refresh. Move to a shared cache (e.g.
// Redis) keyed the same way (by base currency) once available.
const cache = new Map(); // base -> { data, fetchedAt }

async function getRates(base) {
  const cached = cache.get(base);
  const isFresh = cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS;
  if (isFresh) return cached.data;

  try {
    const url = `${RATES_URL}?base=${encodeURIComponent(base)}`;
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Upstream returned ${response.status}`);
    const data = await response.json();
    cache.set(base, { data, fetchedAt: Date.now() });
    return data;
  } catch (err) {
    if (cached) return cached.data; // serve stale data rather than fail
    throw err;
  }
}

const server = http.createServer(async (req, res) => {
  if (req.url === '/health') return res.end('ok');

  if (req.url?.startsWith('/rates')) {
    const { searchParams } = new URL(req.url, 'http://localhost');
    const base = (searchParams.get('base') || 'USD').toUpperCase();

    try {
      const data = await getRates(base);
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify(data));
    } catch (err) {
      res.statusCode = 502;
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify({ error: 'Failed to fetch exchange rates' }));
    }
  }

  res.statusCode = 404; res.end();
});
server.listen(process.env.PORT ?? 3000);

