import { test, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import { getRates, handleRequest, cache, CACHE_TTL_MS } from '../src/server.js';

function makeRes() {
  return {
    statusCode: 200,
    headers: {},
    body: '',
    setHeader(key, value) { this.headers[key] = value; },
    end(chunk) { this.body = chunk ?? ''; },
  };
}

function fetchOk(data) {
  return async () => ({ ok: true, status: 200, json: async () => data });
}

beforeEach(() => {
  cache.clear();
});

test('getRates fetches from upstream and caches on a cold miss', async (t) => {
  const data = { base: 'USD', rates: { EUR: 0.9 } };
  t.mock.method(globalThis, 'fetch', fetchOk(data));

  const result = await getRates('USD');

  assert.deepEqual(result, data);
  assert.equal(globalThis.fetch.mock.calls.length, 1);
  assert.match(globalThis.fetch.mock.calls[0].arguments[0], /base=USD/);
});

test('getRates serves fresh cached data without calling fetch again', async (t) => {
  const cached = { base: 'USD', rates: { EUR: 0.5 } };
  cache.set('USD', { data: cached, fetchedAt: Date.now() });
  t.mock.method(globalThis, 'fetch', async () => {
    throw new Error('should not be called');
  });

  const result = await getRates('USD');

  assert.deepEqual(result, cached);
  assert.equal(globalThis.fetch.mock.calls.length, 0);
});

test('getRates serves stale cached data when the upstream fetch fails', async (t) => {
  const stale = { base: 'USD', rates: { EUR: 0.4 } };
  cache.set('USD', { data: stale, fetchedAt: Date.now() - CACHE_TTL_MS - 1000 });
  t.mock.method(globalThis, 'fetch', async () => {
    throw new Error('upstream down');
  });

  const result = await getRates('USD');

  assert.deepEqual(result, stale);
});

test('getRates throws when the upstream fetch fails and there is no cache', async (t) => {
  t.mock.method(globalThis, 'fetch', async () => {
    throw new Error('upstream down');
  });

  await assert.rejects(() => getRates('EUR'), /upstream down/);
});

test('getRates throws when the upstream response is not ok and there is no cache', async (t) => {
  t.mock.method(globalThis, 'fetch', async () => ({ ok: false, status: 500 }));

  await assert.rejects(() => getRates('EUR'), /Upstream returned 500/);
});

test('handleRequest responds to /health with ok', async () => {
  const res = makeRes();

  await handleRequest({ url: '/health' }, res);

  assert.equal(res.body, 'ok');
});

test('handleRequest defaults /rates to base USD', async (t) => {
  const data = { base: 'USD', rates: { EUR: 0.9 } };
  t.mock.method(globalThis, 'fetch', fetchOk(data));
  const res = makeRes();

  await handleRequest({ url: '/rates' }, res);

  assert.equal(res.statusCode, 200);
  assert.equal(res.headers['Content-Type'], 'application/json');
  assert.deepEqual(JSON.parse(res.body), data);
  assert.match(globalThis.fetch.mock.calls[0].arguments[0], /base=USD/);
});

test('handleRequest uppercases a lowercase base query param', async (t) => {
  const data = { base: 'EUR', rates: { USD: 1.1 } };
  t.mock.method(globalThis, 'fetch', fetchOk(data));
  const res = makeRes();

  await handleRequest({ url: '/rates?base=eur' }, res);

  assert.match(globalThis.fetch.mock.calls[0].arguments[0], /base=EUR/);
});

test('handleRequest returns 502 with an error body when rates cannot be fetched', async (t) => {
  t.mock.method(globalThis, 'fetch', async () => {
    throw new Error('upstream down');
  });
  const res = makeRes();

  await handleRequest({ url: '/rates?base=gbp' }, res);

  assert.equal(res.statusCode, 502);
  assert.deepEqual(JSON.parse(res.body), { error: 'Failed to fetch exchange rates' });
});

test('handleRequest returns 404 for unknown routes', async () => {
  const res = makeRes();

  await handleRequest({ url: '/nope' }, res);

  assert.equal(res.statusCode, 404);
});

